std::vector<std::pair<Point, Point>> edges;
std::vector<double> face_areas;
for (auto it = rt.finite_facets_begin(); it != rt.finite_facets_end(); ++it) {
    if (it->second < threshold) {
        continue;
    }
    auto dual_vertex1 = rt.dual(it);
    auto dual_vertex2 = rt.dual(it->next());
    auto dual_vertex3 = rt.dual(it->next()->next());
    edges.emplace_back(dual_vertex1, dual_vertex2);
    edges.emplace_back(dual_vertex2, dual_vertex3);
    edges.emplace_back(dual_vertex3, dual_vertex1);
    face_areas.push_back(it->second);
}
std::vector<std::vector<std::size_t>> faces;
for (std::size_t i = 0; i < edges.size(); i += 3) {
    faces.push_back({i, i + 1, i + 2});
}
return Mesh<Point, double>(std::move(edges), std::move(faces), std::move(face_areas));

